parameters.jsCode:
const raw = $json.output;

let report;

try {
  report = typeof raw === 'string'
    ? JSON.parse(raw)
    : raw;
} catch (error) {
  return {
    json: {
      success: false,
      error: "Could not parse Report Writer output",
      raw_output: raw
    }
  };
}

return {
  json: {
    business_name: report.business_name || "Not Available",
    executive_summary: report.executive_summary || "Not Available",
    business_performance: report.business_performance || "Not Available",
    trend_analysis: report.trend_analysis || "Not Available",
    forecast: report.forecast || "Not Available",
    risk_analysis: report.risk_analysis || "Not Available",
    key_insights: report.key_insights || "Not Available",
    opportunities: report.opportunities || "Not Available",
    recommendations: report.recommendations || "Not Available",
    overall_outlook: report.overall_outlook || "Not Available"
  }
};

